import{_ as o,l as i,o as e,c as l,v as r,p as s,x as t,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"财政-货币主导","description":"","frontmatter":{"title":"财政-货币主导","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/fiscal-monetary-dominance.md","filePath":"econ/fiscal-monetary-dominance.md","lastUpdated":1789023840000}'),c={name:"econ/fiscal-monetary-dominance.md"};function B(A,a,m,h,_,u){const n=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="财政-货币主导" tabindex="-1">财政-货币主导 <a class="header-anchor" href="#财政-货币主导" aria-label="Permalink to &quot;财政-货币主导&quot;">​</a></h1><div class="epigraph"><p>价格水平由谁的规则钉住：货币主导下财政必须最终适应；财政主导下货币适应债，通胀成为清算工具。</p><footer>—— Sargent and Wallace, Some Unpleasant Monetarist Arithmetic, 1981；Leeper, Equilibria under Active and Passive Monetary and Fiscal Policies, JME 1991</footer></div><p><a href="/econ/debt-sustainability">上一课</a>的 \\(s\\) 反应函数被当成给定。本课缺口是 <strong>谁适应谁</strong>：Sargent–Wallace 的算术与 Leeper 的主动/被动。不重写 \\(r-g\\) 公式，不把 CBDC 提前当主工具。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>货币数量或泰勒规则要钉住价格，政府跨期预算必须在某个未来用税收或支出闭合——否则债爆炸或靠铸币税。Sargent–Wallace：若财政不适应，紧货币今天可以意味着更高的未来通胀。Leeper：主动货币+被动财政，或被动货币+主动财政，才能有唯一（局部）均衡；两个都主动则冲突。缺口是给锚定课的「财政可以解钉」一条规则语言。</p><p><span class="marginnote">Sargent and Wallace, FRB Minneapolis <em>Quarterly Review</em> 1981。Leeper, <em>JME</em> 1991。Woodford 的财政理论讨论。Cochrane 的 FTPL 是有争议的延伸，本课用 Leeper 的主动被动，不把争论写成已决。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>线性 NK 加政府预算。货币规则：对通胀的反应 \\(\\phi_\\pi\\)。财政：盈余对债的反应 \\(\\gamma\\)。BK 式计数：一对一的主动被动组合给出决定性。财政主导：盈余不跟债走，价格水平跳升以稀释名义债，使预算闭合（财政价格理论的核心机制）。再谈判、指数化债、外币债削弱稀释通道，把经济推向 Arellano 违约。</p>',8)),(e(),s(E,null,{default:t(()=>[p(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20AM%5B%22%E4%B8%BB%E5%8A%A8%E8%B4%A7%E5%B8%81%22%5D%20--%3E%20NEED%5B%22%E9%9C%80%E8%A6%81%E8%A2%AB%E5%8A%A8%E8%B4%A2%E6%94%BF%22%5D%0A%20%20AF%5B%22%E4%B8%BB%E5%8A%A8%E8%B4%A2%E6%94%BF%22%5D%20--%3E%20NEED2%5B%22%E9%9C%80%E8%A6%81%E8%A2%AB%E5%8A%A8%E8%B4%A7%E5%B8%81%22%5D%0A%20%20BOTH%5B%22%E5%8F%8C%E4%B8%BB%E5%8A%A8%22%5D%20--%3E%20CONF%5B%22%E5%86%B2%E7%AA%81%20%2F%20%E4%B8%8D%E5%AE%9A%E6%88%96%E7%88%86%E7%82%B8%22%5D%0A%20%20DOM%5B%22%E8%B4%A2%E6%94%BF%E4%B8%BB%E5%AF%BC%22%5D%20--%3E%20INF%5B%22%E9%80%9A%E8%83%80%E6%B8%85%E7%AE%97%E5%90%8D%E4%B9%89%E5%80%BA%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与沟通：Delphic 若揭示「财政不会适应」，锚定失败。与 HANK：稀释的分配取决于谁持有名义债（Doepke–Schneider）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是跨期预算必须在均衡成立。不是规范上「应该违约或应该征税」，而是价格、违约、或盈余三者必居其一（或组合）。非常规货币扩张央行持有的政府债，把利息风险移到公共部门，主导问题更显性——后课资产负债表。独立央行是承诺装置，不能单独取消算术。</p><p>不快的算术：今天的反通胀若提高实际利率、加重债，而财政不跟，人会预期未来的货币投降。</p><p><span class="marginnote">时间不一致课的通胀偏误是另一条线（Barro–Gordon）。本课是预算闭合，不是菲利普斯欺骗。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不主张「任意债都可以靠物价一次跳清」。流动性陷阱、ZLB、长期债的估值效应使定量复杂。下一课用历史看银行危机，不是同一条会计。不把黄金作为货币规则重写。</p><p>后课默认：决定性要声明货币与财政谁主动；财政主导是通胀清算名义债。下一课：银行危机的历史模式。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>不愉快算术：财政不适应时，紧货币可预示未来通胀。</li><li>Leeper：主动/被动配对才能局部决定。</li><li>稀释、违约、增税是预算闭合的三个出口。</li><li>出处：Sargent and Wallace 1981；Leeper, <em>JME</em> 1991。</li></ul>',10))])}const S=o(c,[["render",B]]);export{D as __pageData,S as default};
